// Tracee: Prepare process to be traced by parent (often after fork, before exec)
ptrace(PTRACE_TRACEME, 0, NULL, NULL);

// Tracer: Attach to running process (must have permissions)
long ret = ptrace(PTRACE_ATTACH, target_pid, NULL, NULL);

// Tracer: Wait for tracee to stop (e.g., SIGSTOP sent by ATTACH)
waitpid(target_pid, &status, 0);

// Tracer: Read word (long) of data from tracee's memory address
long data = ptrace(PTRACE_PEEKDATA, target_pid, (void*)target_addr, NULL);

// Tracer: Write word (long) of data to tracee's memory address
long new_val = 12345;
ptrace(PTRACE_POKEDATA, target_pid, (void*)target_addr, (void*)new_val);

// Tracer: Restart execution (or PTRACE_SYSCALL for syscall tracing)
ptrace(PTRACE_CONT, target_pid, NULL, NULL);

// Tracer: Detach from the process
ptrace(PTRACE_DETACH, target_pid, NULL, NULL);
